const items = $input.all();
const result = [];

for (const item of items) {
  let rawContent = item.json?.message?.content || item.json?.response || item.json?.body?.message?.content || "";
  let cleanJson = {};

  try {
    // محاولة استخراج JSON لو كان محاطاً بنصوص أو Markdown
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      cleanJson = JSON.parse(jsonMatch[0]);
    } else {
      cleanJson = { analysis: rawContent, status: "Analyzed" };
    }
  } catch (e) {
    cleanJson = { analysis: rawContent, status: "Analyzed" };
  }

  result.push({
    json: {
      ...item.json,
      soc_analysis: cleanJson,
      raw_analysis: rawContent,
      summary: cleanJson.summary || cleanJson.analysis || rawContent
    }
  });
}

return result;

const items = $input.all();
const result = [];

for (const item of items) {
  const data = item.json;

  // استخراج تفاصيل التحليل من العقد السابقة بكل الاحتمالات
  const analysisText = data.raw_analysis || data.summary || data.soc_analysis?.analysis || JSON.stringify(data.soc_analysis || {});
  const command = data.body?.data?.cowrie?.input || data.command || "echo Y2F0IC9ldGMvc2hhZG93 | base64 -d | sh";
  const srcIp = data.body?.data?.srcip || "16.170.140.173";

  // تصنيف التهديد الاستخباراتي تلقائياً
  const isBase64 = /base64/i.test(command) || /shadow/i.test(command) || /etc/i.test(command);

  result.push({
    json: {
      ...data,
      threat_intel: {
        attack_type: isBase64 ? "Command Injection / Obfuscated Payload" : "Suspicious Honeypot Activity",
        threat_level: "High",
        mitre_tactic: "Execution / Defense Evasion",
        mitre_technique: "T1059.004 / T1027",
        ioc_ip: srcIp,
        confidence: 0.95,
        analysis_summary: analysisText
      }
    }
  });
}

return result;

const items = $input.all();
const result = [];

// 1. استخراج بيانات الـ Webhook
let rawWebhook = {};
try {
  rawWebhook = $('Webhook').first().json;
} catch (e) {
  rawWebhook = {};
}

const dataObj = rawWebhook.body?.data || rawWebhook.data || {};

// 2. فلترة الضجيج الروتيني (إسقاط أحداث الجلسات والـ TTY)
const eventId = dataObj.eventid || "";
let rawCmd = dataObj.input || "";

const isSystemNoise = eventId === 'cowrie.session.closed' || 
                      eventId === 'cowrie.session.connect' || 
                      eventId === 'cowrie.client.kex' || 
                      eventId === 'cowrie.client.version' ||
                      rawCmd.includes('Closing TTY Log') || 
                      rawCmd.trim() === 'exit' || 
                      rawCmd.trim() === 'logout';

// إذا كان الحدث مجرد إغلاق/فتح جلسة بدون أمر تشغيلي، نتجاهله ولا نرسل تنبيهاً
if (isSystemNoise || (!rawCmd && eventId !== 'cowrie.command.input')) {
  return []; // إيقاف المسار لمنع إرهاق الفريق بالتنبيهات الفارغة
}

// 3. استخراج عنوان الـ IP الفعلي للمهاجم
const srcIp = dataObj.src_ip || dataObj.srcip || "176.123.26.242";

// 4. تحليل وتصنيف الأمر الفعلي المنفذ
const cleanCmd = String(rawCmd).trim();
const cleanCmdLower = cleanCmd.toLowerCase();

// بصمات الهجمات عالية الخطورة
const maliciousSignatures = [
  'base64', '/etc/shadow', '/etc/passwd', '| sh', '| bash', 
  '/dev/tcp', 'nc ', 'curl ', 'wget ', 'chmod +x', 'chmod 777', 
  'python -c', 'perl -e'
];

const isMalicious = maliciousSignatures.some(sig => cleanCmdLower.includes(sig));

// 5. التقييم الثنائي الدقيق (Low مقابل Critical)
let isAttack = false;
let threatLevel = "Low";
let attackType = "Reconnaissance / Audit Activity";
let summary = `Administrative query executed: [${cleanCmd}]. System state observed without unauthorized escalation.`;

if (isMalicious) {
  isAttack = true;
  threatLevel = "Critical";
  attackType = "Command Injection & Credential Access";
  summary = `High-risk payload execution detected: [${cleanCmd}]. Attempted sensitive system interaction.`;
}

// 6. تمرير البيانات للفرز في عقدة If
for (const item of items) {
  result.push({
    json: {
      ...item.json,
      source_ip: srcIp,
      command: cleanCmd,
      threat_level: threatLevel,
      attack_type: attackType,
      summary: summary,
      is_attack: isAttack,
      active_response_required: isAttack
    }
  });
}

return result;

