const raw = $input.first().json;
const incidentId = "INC-" + Math.floor(100000 + Math.random() * 900000);
const dateStr = new Date().toUTCString();

const sourceIp = $('Agent 3 - Prepare Security Report').item?.json?.source_ip || '16.170.140.173';
const cmd = $('Agent 3 - Prepare Security Report').item?.json?.command || 'echo Y2F0IC9ldGMvc2hhZG93 | base64 -d | sh';
const attackType = $('Agent 3 - Prepare Security Report').item?.json?.agent_1?.attack_type || 'Base64 Obfuscated Credential Dumping';
const analysisText = $('Agent 3 - Prepare Security Report').item?.json?.agent_1?.analysis || 'Adversary executed base64-encoded shell commands to evade signature detection, attempting direct exfiltration of privileged system credentials (/etc/shadow).';
const severity = ($('Agent 3 - Prepare Security Report').item?.json?.agent_1?.severity || 'CRITICAL').toUpperCase();

const htmlContent = `<!DOCTYPE html>
<html lang="en">
