    }
    .header .subtitle {
      margin: 6px 0 0;
      font-size: 13px;
      color: #fca5a5;
    }
    .header-badge {
      background: var(--danger);
      color: white;
      padding: 6px 14px;
      border-radius: 6px;
      font-weight: 800;
      font-size: 14px;
      letter-spacing: 1px;
      box-shadow: 0 0 15px rgba(239, 68, 68, 0.4);
    }
    .content {
      padding: 35px 40px;
    }
    .metrics-grid {
