      font-size: 13px;
      overflow-x: auto;
      margin: 0;
    }
    .analysis-box {
      background-color: #1e1b4b;
      border: 1px solid #312e81;
      border-left: 4px solid #818cf8;
      border-radius: 8px;
      padding: 18px;
      color: #e0e7ff;
