          <div class="metric-value">Wazuh SIEM / n8n</div>
        </div>
      </div>

      <div class="section-title">1. Raw Exploit Payload / Execution Artifact</div>
      <pre class="code-block"><code>${cmd}</code></pre>

      <div class="section-title">2. MITRE ATT&CK Mapping & Categorization</div>
      <table class="mitre-table">
        <thead>
          <tr>
            <th>Tactic</th>
